import {
  CircleAlert,
  CircleCheckBig,
  Info,
  Star,
  TriangleAlert,
  X,
} from "lucide-react";
import type {
  CSSProperties,
  FocusEvent,
  HTMLAttributes,
  MouseEvent,
  ReactNode,
} from "react";
import { Button } from "./Button";
import { mergeClasses } from "./classes";
import { roundedClasses, type Rounded } from "./form";
import { Icon, type IconComponent, type IconSize } from "./Icon";
import type { Shadow, ThemeInput } from "./theme";
import { BalsaThemeContext, useResolvedThemeProps } from "./theme-context";
import type { ActionColor, SemanticColor } from "./types";

export type ToastVariant = "surface" | "soft" | "outline" | "glass";
export type ToastSize = "sm" | "md" | "lg";

export interface ToastProps extends Omit<
  HTMLAttributes<HTMLElement>,
  "title" | "children" | "color" | "onPause"
> {
  id: string;
  title: string;
  "data-balsa"?: string;
  "data-palette"?: string;
  description?: string;
  color?: SemanticColor;
  variant?: ToastVariant;
  size?: ToastSize;
  rounded?: Rounded;
  shadow?: Shadow;
  icon?: IconComponent;
  actionLabel?: string;
  dismissible?: boolean;
  closeLabel?: string;
  theme?: ThemeInput;
  onAction?: () => void;
  onDismiss?: () => void;
  onPause?: () => void;
  onResume?: () => void;
  action?: ReactNode | ((dismiss: () => void) => ReactNode);
  children?: ReactNode;
}

const defaultIcons: Readonly<Record<SemanticColor, IconComponent>> = {
  primary: Info,
  secondary: Info,
  accent: Star,
  destructive: CircleAlert,
  success: CircleCheckBig,
  warning: TriangleAlert,
  info: Info,
};
const colorVariantClasses: Readonly<
  Record<SemanticColor, Record<ToastVariant, string[]>>
> = {
  primary: {
    surface: ["border-balsa-primary/40", "bg-balsa-surface-elevated", "text-balsa-surface-elevated-foreground"],
    soft: ["border-balsa-primary/25", "bg-balsa-primary/15", "text-balsa-primary"],
    outline: ["border-balsa-primary", "bg-balsa-background", "text-balsa-foreground"],
    glass: ["border-balsa-primary/40", "bg-balsa-primary/10", "text-balsa-primary", "backdrop-balsa"],
  },
  secondary: {
    surface: ["border-balsa-secondary/40", "bg-balsa-surface-elevated", "text-balsa-surface-elevated-foreground"],
    soft: ["border-balsa-secondary/25", "bg-balsa-secondary/15", "text-balsa-secondary"],
    outline: ["border-balsa-secondary", "bg-balsa-background", "text-balsa-foreground"],
    glass: ["border-balsa-secondary/40", "bg-balsa-secondary/10", "text-balsa-secondary", "backdrop-balsa"],
  },
  accent: {
    surface: ["border-balsa-accent/40", "bg-balsa-surface-elevated", "text-balsa-surface-elevated-foreground"],
    soft: ["border-balsa-accent/25", "bg-balsa-accent/15", "text-balsa-accent"],
    outline: ["border-balsa-accent", "bg-balsa-background", "text-balsa-foreground"],
    glass: ["border-balsa-accent/40", "bg-balsa-accent/10", "text-balsa-accent", "backdrop-balsa"],
  },
  destructive: {
    surface: ["border-balsa-destructive/40", "bg-balsa-surface-elevated", "text-balsa-surface-elevated-foreground"],
    soft: ["border-balsa-destructive/25", "bg-balsa-destructive/15", "text-balsa-destructive"],
    outline: ["border-balsa-destructive", "bg-balsa-background", "text-balsa-foreground"],
    glass: ["border-balsa-destructive/40", "bg-balsa-destructive/10", "text-balsa-destructive", "backdrop-balsa"],
  },
  success: {
    surface: ["border-balsa-success/40", "bg-balsa-surface-elevated", "text-balsa-surface-elevated-foreground"],
    soft: ["border-balsa-success/25", "bg-balsa-success/15", "text-balsa-success"],
    outline: ["border-balsa-success", "bg-balsa-background", "text-balsa-foreground"],
    glass: ["border-balsa-success/40", "bg-balsa-success/10", "text-balsa-success", "backdrop-balsa"],
  },
  warning: {
    surface: ["border-balsa-warning/40", "bg-balsa-surface-elevated", "text-balsa-surface-elevated-foreground"],
    soft: ["border-balsa-warning/25", "bg-balsa-warning/15", "text-balsa-warning"],
    outline: ["border-balsa-warning", "bg-balsa-background", "text-balsa-foreground"],
    glass: ["border-balsa-warning/40", "bg-balsa-warning/10", "text-balsa-warning", "backdrop-balsa"],
  },
  info: {
    surface: ["border-balsa-info/40", "bg-balsa-surface-elevated", "text-balsa-surface-elevated-foreground"],
    soft: ["border-balsa-info/25", "bg-balsa-info/15", "text-balsa-info"],
    outline: ["border-balsa-info", "bg-balsa-background", "text-balsa-foreground"],
    glass: ["border-balsa-info/40", "bg-balsa-info/10", "text-balsa-info", "backdrop-balsa"],
  },
};
const iconColorClasses: Readonly<Record<SemanticColor, string>> = {
  primary: "text-balsa-primary",
  secondary: "text-balsa-secondary",
  accent: "text-balsa-accent",
  destructive: "text-balsa-destructive",
  success: "text-balsa-success",
  warning: "text-balsa-warning",
  info: "text-balsa-info",
};
const actionColorMap: Readonly<Record<SemanticColor, ActionColor>> = {
  primary: "primary",
  secondary: "secondary",
  accent: "accent",
  destructive: "destructive",
  success: "primary",
  warning: "accent",
  info: "primary",
};
const sizeClasses: Readonly<Record<ToastSize, string>> = {
  sm: "p-balsa-md text-sm",
  md: "p-balsa-lg text-sm",
  lg: "p-balsa-xl text-base",
};
const contentGapClasses: Readonly<Record<ToastSize, string>> = {
  sm: "gap-balsa-md",
  md: "gap-balsa-lg",
  lg: "gap-balsa-xl",
};
const iconSizes: Readonly<Record<ToastSize, IconSize>> = {
  sm: "md",
  md: "lg",
  lg: "xl",
};
const titleSizeClasses: Readonly<Record<ToastSize, string>> = {
  sm: "text-sm",
  md: "text-base",
  lg: "text-lg",
};

export function Toast(rawProps: ToastProps) {
  const { props, theme } = useResolvedThemeProps("toast", "overlays", rawProps, {
    variant: "surface",
    size: "md",
    rounded: "lg",
    shadow: "auto",
  } as const);
  const {
    id,
    title,
    "data-balsa": _dataBalsa,
    "data-palette": dataPalette,
    description,
    color = "primary",
    variant,
    size,
    rounded,
    shadow,
    icon,
    actionLabel,
    dismissible = true,
    closeLabel = "Dismiss notification",
    theme: _themeInput,
    onAction,
    onDismiss,
    onPause,
    onResume,
    action,
    className,
    style,
    children,
    onMouseEnter,
    onMouseLeave,
    onFocus,
    onBlur,
    ...domProps
  } = props;
  void _dataBalsa;
  void _themeInput;

  const currentIcon = icon ?? defaultIcons[color];
  const isTintedVariant = variant === "soft" || variant === "glass";
  const titleId = `${id}-title`;
  const descriptionId = description ? `${id}-description` : undefined;
  const actionContent = typeof action === "function" ? action(() => onDismiss?.()) : action;

  const classes = mergeClasses(
    "pointer-events-auto relative w-full min-w-0 border font-balsa-body shadow-balsa-surface outline-none",
    sizeClasses[size],
    roundedClasses[rounded],
    colorVariantClasses[color][variant],
    className,
  );

  function pause(event: MouseEvent<HTMLElement> | FocusEvent<HTMLElement>): void {
    if (event.type === "mouseenter") onMouseEnter?.(event as MouseEvent<HTMLElement>);
    else onFocus?.(event as FocusEvent<HTMLElement>);
    onPause?.();
  }

  function resume(event: MouseEvent<HTMLElement> | FocusEvent<HTMLElement>): void {
    if (event.type === "mouseleave") onMouseLeave?.(event as MouseEvent<HTMLElement>);
    else onBlur?.(event as FocusEvent<HTMLElement>);
    onResume?.();
  }

  return (
    <BalsaThemeContext.Provider value={theme}>
      <article
        {...domProps}
        id={id}
        data-balsa="toast"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-palette={dataPalette}
        data-color={color}
        data-variant={variant}
        data-size={size}
        data-rounded={rounded}
        data-shadow={shadow}
        role={color === "destructive" ? "alert" : "status"}
        aria-live={color === "destructive" ? "assertive" : "polite"}
        aria-atomic="true"
        aria-labelledby={titleId}
        aria-describedby={descriptionId}
        className={classes}
        style={
          {
            ...theme.explicitPresentation?.style,
            ...style,
          } as CSSProperties
        }
        onMouseEnter={pause}
        onMouseLeave={resume}
        onFocus={pause}
        onBlur={resume}
      >
        <div className={mergeClasses("flex min-w-0 items-start", contentGapClasses[size])}>
          <Icon
            icon={currentIcon}
            size={iconSizes[size]}
            className={mergeClasses(
              "shrink-0",
              isTintedVariant ? "text-current" : iconColorClasses[color],
            )}
          />
          <div className={mergeClasses("min-w-0 flex-1", dismissible ? "pr-9" : "")}>
            <h3
              id={titleId}
              className={mergeClasses("m-0 font-semibold leading-tight", titleSizeClasses[size])}
            >
              {title}
            </h3>
            {description ? (
              <p
                id={descriptionId}
                className={mergeClasses(
                  "mt-balsa-3xs leading-relaxed",
                  isTintedVariant ? "text-current" : "text-balsa-muted-foreground",
                )}
              >
                {description}
              </p>
            ) : null}
            {children}
          </div>
        </div>

        {dismissible ? (
          <Button
            data-balsa-toast-close=""
            size={null}
            shape="fab"
            variant="outline"
            color="secondary"
            prefixIcon={X}
            aria-label={closeLabel}
            className={mergeClasses(
              "absolute right-2 top-2 size-8 min-h-0 min-w-0 border-0 bg-transparent p-0 text-lg shadow-none",
              isTintedVariant
                ? "text-current hover:bg-current/15 active:bg-current/25"
                : "text-balsa-muted-foreground hover:bg-balsa-muted hover:text-balsa-foreground active:bg-balsa-muted",
            )}
            onClick={onDismiss}
          />
        ) : null}

        {actionLabel || actionContent ? (
          <div
            data-balsa-toast-action=""
            className="mt-balsa-md flex min-w-0 justify-end gap-balsa-xs"
          >
            {actionContent ?? (
              <Button
                variant="outline"
                color={actionColorMap[color]}
                size="sm"
                onClick={onAction}
              >
                {actionLabel}
              </Button>
            )}
          </div>
        ) : null}
      </article>
    </BalsaThemeContext.Provider>
  );
}

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type FocusEvent,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { useBalsaPortalScope } from "./BalsaPortalScope";
import { mergeClasses } from "./classes";
import type { Rounded } from "./form";
import type { IconComponent } from "./Icon";
import {
  capturePortalPresentation,
  type PortalPresentationSnapshot,
} from "./portal-core";
import type { ThemeInput } from "./theme";
import {
  BalsaThemeContext,
  useControllableState,
  useResolvedThemeProps,
} from "./theme-context";
import { Toast, type ToastSize, type ToastVariant } from "./Toast";
import type { SemanticColor } from "./types";

export type ToastPosition =
  | "top-start"
  | "top-center"
  | "top-end"
  | "bottom-start"
  | "bottom-center"
  | "bottom-end";
export type ToastDismissReason = "close" | "escape" | "timeout" | "action";

export interface ToastItem {
  id: string;
  title: string;
  description?: string;
  color?: SemanticColor;
  variant?: ToastVariant;
  size?: ToastSize;
  rounded?: Rounded;
  icon?: IconComponent;
  actionLabel?: string;
  actionDismiss?: boolean;
  dismissible?: boolean;
  closeLabel?: string;
  duration?: number;
  sticky?: boolean;
}

export interface ToastActionControls {
  dismiss: () => void;
  run: () => void;
}

export interface ToastViewportProps extends Omit<
  HTMLAttributes<HTMLElement>,
  "children" | "value" | "defaultValue"
> {
  "data-balsa"?: string;
  "data-palette"?: string;
  label?: string;
  position?: ToastPosition;
  limit?: number;
  duration?: number;
  pauseOnHover?: boolean;
  pauseOnFocus?: boolean;
  contained?: boolean;
  theme?: ThemeInput;
  value?: readonly ToastItem[];
  defaultValue?: readonly ToastItem[];
  onValueChange?: (value: readonly ToastItem[]) => void;
  onAction?: (item: ToastItem) => void;
  onDismiss?: (item: ToastItem, reason: ToastDismissReason) => void;
  action?: (item: ToastItem, controls: ToastActionControls) => ReactNode;
}

interface TimerState {
  duration: number;
  remaining: number;
  startedAt: number;
  handle?: ReturnType<typeof setTimeout>;
}

const positionClasses: Readonly<Record<ToastPosition, string[]>> = {
  "top-start": ["left-4 top-4 items-start"],
  "top-center": ["left-1/2 top-4 -translate-x-1/2 items-center"],
  "top-end": ["right-4 top-4 items-end"],
  "bottom-start": ["bottom-4 left-4 flex-col-reverse items-start"],
  "bottom-center": ["bottom-4 left-1/2 -translate-x-1/2 flex-col-reverse items-center"],
  "bottom-end": ["bottom-4 right-4 flex-col-reverse items-end"],
};
const observedPresentationAttributes = [
  "style",
  "data-theme",
  "data-theme-base",
  "data-palette",
  "data-balsa-adapt",
];

function samePresentation(
  current: PortalPresentationSnapshot | null,
  next: PortalPresentationSnapshot,
): boolean {
  if (!current
    || current.themeId !== next.themeId
    || current.themeBase !== next.themeBase
    || current.paletteId !== next.paletteId
    || current.adapt !== next.adapt) {
    return false;
  }
  const currentEntries = Object.entries(current.style);
  const nextEntries = Object.entries(next.style);
  return currentEntries.length === nextEntries.length
    && nextEntries.every(([property, value]) => current.style[property as `--balsa-${string}`] === value);
}

export function ToastViewport(rawProps: ToastViewportProps) {
  const { props, theme } = useResolvedThemeProps("toast", "overlays", rawProps, {});
  const {
    "data-balsa": _dataBalsa,
    "data-palette": dataPalette,
    label = "Notifications",
    position = "bottom-end",
    limit = 5,
    duration = 5000,
    pauseOnHover = true,
    pauseOnFocus = true,
    contained = false,
    theme: _themeInput,
    value,
    defaultValue = [],
    onValueChange,
    onAction,
    onDismiss,
    action,
    className,
    style,
    onMouseEnter,
    onMouseLeave,
    onFocus,
    onBlur,
    ...domProps
  } = props;
  void _dataBalsa;
  void _themeInput;

  const [current, setItems] = useControllableState<readonly ToastItem[]>({
    value,
    defaultValue,
    onChange: onValueChange,
  });
  const scope = useBalsaPortalScope();
  const anchorRef = useRef<HTMLSpanElement | null>(null);
  const timersRef = useRef(new Map<string, TimerState>());
  const pauseReasonsRef = useRef(new Set<string>());
  const itemsRef = useRef(current);
  const limitRef = useRef(limit);
  const durationRef = useRef(duration);
  const callbacksRef = useRef({ onAction, onDismiss });
  const themeRef = useRef(theme);
  const [mounted, setMounted] = useState(false);
  const [portalPresentation, setPortalPresentation] = useState<PortalPresentationSnapshot | null>(null);
  itemsRef.current = current;
  limitRef.current = limit;
  durationRef.current = duration;
  callbacksRef.current = { onAction, onDismiss };
  themeRef.current = theme;

  const safeLimit = Number.isFinite(limit)
    ? Math.max(1, Math.min(10, Math.floor(limit)))
    : 5;
  const visibleItems = current.slice(-safeLimit).reverse();
  const portalHost = contained ? null : (scope?.host ?? (mounted ? document.body : null));

  function itemDuration(item: ToastItem): number {
    const candidate = item.duration ?? durationRef.current;
    return Number.isFinite(candidate) && candidate > 0 ? candidate : 5000;
  }

  function clearTimer(timer: TimerState): void {
    if (timer.handle !== undefined) clearTimeout(timer.handle);
    timer.handle = undefined;
  }

  function dismiss(id: string, reason: ToastDismissReason): void {
    const item = itemsRef.current.find((candidate) => candidate.id === id);
    if (!item) return;
    const timer = timersRef.current.get(id);
    if (timer) clearTimer(timer);
    timersRef.current.delete(id);
    const next = itemsRef.current.filter((candidate) => candidate.id !== id);
    itemsRef.current = next;
    setItems(next);
    callbacksRef.current.onDismiss?.(item, reason);
  }

  function scheduleTimer(item: ToastItem, timer: TimerState): void {
    clearTimer(timer);
    if (item.sticky || pauseReasonsRef.current.size > 0) return;
    timer.startedAt = Date.now();
    timer.handle = setTimeout(() => dismiss(item.id, "timeout"), timer.remaining);
  }

  function syncTimers(): void {
    const ids = new Set(itemsRef.current.map(({ id }) => id));
    for (const [id, timer] of timersRef.current) {
      if (!ids.has(id)) {
        clearTimer(timer);
        timersRef.current.delete(id);
      }
    }
    for (const item of itemsRef.current) {
      if (item.sticky) {
        const timer = timersRef.current.get(item.id);
        if (timer) clearTimer(timer);
        timersRef.current.delete(item.id);
        continue;
      }
      const nextDuration = itemDuration(item);
      const existing = timersRef.current.get(item.id);
      if (existing?.duration === nextDuration) continue;
      if (existing) clearTimer(existing);
      const timer: TimerState = {
        duration: nextDuration,
        remaining: nextDuration,
        startedAt: 0,
      };
      timersRef.current.set(item.id, timer);
      scheduleTimer(item, timer);
    }
  }

  function pause(reason: string): void {
    if (pauseReasonsRef.current.has(reason)) return;
    pauseReasonsRef.current.add(reason);
    const now = Date.now();
    for (const timer of timersRef.current.values()) {
      if (timer.handle === undefined) continue;
      timer.remaining = Math.max(0, timer.remaining - (now - timer.startedAt));
      clearTimer(timer);
    }
  }

  function resume(reason: string): void {
    pauseReasonsRef.current.delete(reason);
    if (pauseReasonsRef.current.size > 0) return;
    for (const item of itemsRef.current) {
      const timer = timersRef.current.get(item.id);
      if (timer) scheduleTimer(item, timer);
    }
  }

  function runAction(item: ToastItem): void {
    callbacksRef.current.onAction?.(item);
    if (item.actionDismiss !== false) dismiss(item.id, "action");
  }

  function capturePresentation(): void {
    const anchor = anchorRef.current;
    if (!anchor?.isConnected) return;
    const next = capturePortalPresentation(anchor, themeRef.current.presentation);
    setPortalPresentation((currentPresentation) => (
      samePresentation(currentPresentation, next) ? currentPresentation : next
    ));
  }

  useLayoutEffect(() => {
    setMounted(true);
  }, []);

  useLayoutEffect(() => {
    if (!mounted) return;
    const anchor = anchorRef.current;
    if (!anchor) return;
    capturePresentation();
    const observer = new MutationObserver(capturePresentation);
    for (let element: HTMLElement | null = anchor; element; element = element.parentElement) {
      observer.observe(element, {
        attributes: true,
        attributeFilter: observedPresentationAttributes,
      });
    }
    return () => observer.disconnect();
  }, [mounted, contained, scope?.host]);

  useEffect(() => {
    syncTimers();
  }, [current, duration]);

  useEffect(() => {
    if (!mounted) return;

    function handleKeydown(event: KeyboardEvent): void {
      if (event.defaultPrevented || event.key !== "Escape" || itemsRef.current.length === 0) return;
      const currentLimit = Number.isFinite(limitRef.current)
        ? Math.max(1, Math.min(10, Math.floor(limitRef.current)))
        : 5;
      const item = itemsRef.current
        .slice(-currentLimit)
        .reverse()
        .find((candidate) => candidate.dismissible !== false);
      if (!item) return;
      event.preventDefault();
      dismiss(item.id, "escape");
    }

    function handleVisibility(): void {
      if (document.hidden) pause("document-hidden");
      else resume("document-hidden");
    }

    function handleBlur(): void {
      pause("window-blur");
    }

    function handleFocus(): void {
      resume("window-blur");
    }

    document.addEventListener("keydown", handleKeydown);
    document.addEventListener("visibilitychange", handleVisibility);
    window.addEventListener("blur", handleBlur);
    window.addEventListener("focus", handleFocus);
    return () => {
      document.removeEventListener("keydown", handleKeydown);
      document.removeEventListener("visibilitychange", handleVisibility);
      window.removeEventListener("blur", handleBlur);
      window.removeEventListener("focus", handleFocus);
      for (const timer of timersRef.current.values()) clearTimer(timer);
      timersRef.current.clear();
      pauseReasonsRef.current.clear();
    };
  }, [mounted]);

  const presentation = portalPresentation ?? {
    themeId: theme.presentation.id,
    themeBase: theme.presentation.base,
    paletteId: dataPalette,
    style: Object.fromEntries(
      Object.entries(theme.presentation.style).filter(([property]) => property.startsWith("--balsa-")),
    ) as PortalPresentationSnapshot["style"],
  };
  const viewport = mounted ? (
    <section
      {...domProps}
      data-balsa="toast-viewport"
      data-theme={presentation.themeId}
      data-theme-base={presentation.themeBase}
      data-palette={presentation.paletteId}
      data-balsa-adapt={presentation.adapt}
      data-position={position}
      aria-label={label}
      className={mergeClasses(
        "pointer-events-none z-[70] flex max-h-[calc(100dvh-2rem)] max-w-sm gap-balsa-md overflow-y-auto overscroll-contain",
        contained
          ? "absolute w-[calc(100%-2rem)]"
          : "fixed w-[calc(100vw-2rem)]",
        positionClasses[position],
        className,
      )}
      style={
        {
          ...presentation.style,
          ...style,
        } as CSSProperties
      }
      onMouseEnter={(event: MouseEvent<HTMLElement>) => {
        onMouseEnter?.(event);
        if (pauseOnHover) pause("hover");
      }}
      onMouseLeave={(event: MouseEvent<HTMLElement>) => {
        onMouseLeave?.(event);
        if (pauseOnHover) resume("hover");
      }}
      onFocus={(event: FocusEvent<HTMLElement>) => {
        onFocus?.(event);
        if (pauseOnFocus) pause("focus");
      }}
      onBlur={(event: FocusEvent<HTMLElement>) => {
        onBlur?.(event);
        if (!pauseOnFocus) return;
        const next = event.relatedTarget;
        if (next instanceof Node && event.currentTarget.contains(next)) return;
        resume("focus");
      }}
    >
      {visibleItems.map((item) => {
        const controls: ToastActionControls = {
          dismiss: () => dismiss(item.id, "close"),
          run: () => runAction(item),
        };
        return (
          <Toast
            key={item.id}
            id={item.id}
            title={item.title}
            description={item.description}
            color={item.color}
            variant={item.variant}
            size={item.size}
            rounded={item.rounded}
            icon={item.icon}
            actionLabel={item.actionLabel}
            dismissible={item.dismissible}
            closeLabel={item.closeLabel}
            theme={theme.input}
            action={action?.(item, controls)}
            onAction={controls.run}
            onDismiss={controls.dismiss}
          />
        );
      })}
    </section>
  ) : null;

  return (
    <BalsaThemeContext.Provider value={theme}>
      <span
        ref={anchorRef}
        data-balsa="toast-anchor"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-palette={dataPalette}
        className="contents"
        style={theme.explicitPresentation?.style as CSSProperties | undefined}
      >
        {contained ? viewport : (portalHost && viewport ? createPortal(viewport, portalHost) : null)}
      </span>
    </BalsaThemeContext.Provider>
  );
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

